        verify: [vt('tests/unit/audio/synthMusic.test.js'), exists('scripts/assets/synthMusic.mjs', 'assets/audio/music/music_town_day.wav', 'assets/audio/music/music_town_night.wav', 'assets/audio/music/music_harbour.wav', 'assets/audio/music/music_beach.wav', 'assets/audio/music/music_forest.wav', 'assets/audio/music/music_hotel.wav', 'assets/audio/music/music_cafe.wav', 'assets/audio/music/music_office.wav', 'assets/audio/music/music_studio.wav', 'assets/audio/music/music_hall.wav'), npm('check:ledger'), npm('check:size')],
